// Money for one share, in whole 分 (0.01). The platform, not the code,
// decides what is finally paid: whatever the code asks is pulled into the
// share's range, and the last share takes everything left.
import { randomIntegerInclusive } from "./random.mjs";

/**
 * This share's range: at least 每份至少, at most what leaves 每份至少 for
 * every share after it; the last one is exactly what is left.
 */
export function shareRange({ remaining, remainingCount, minEach }) {
  if (remainingCount <= 1)
    return { min: remaining, max: remaining, last: true };
  return {
    min: minEach,
    max: remaining - (remainingCount - 1) * minEach,
    last: false,
  };
}

/** What is paid for `asked`: pulled into the range. */
export function settle(asked, share) {
  return Math.min(share.max, Math.max(share.min, asked));
}

/** 2000 → "20.00". */
export function formatAmount(amount) {
  if (!Number.isSafeInteger(amount))
    throw new TypeError("format 要一个整数（分）");
  const sign = amount < 0 ? "-" : "";
  const value = Math.abs(amount);
  return `${sign}${Math.floor(value / 100)}.${String(value % 100).padStart(2, "0")}`;
}

/** What is left, shared out evenly (rounded down), within the range. */
export function evenAmount(hongbao, share) {
  return settle(Math.floor(hongbao.remaining / hongbao.remainingCount), share);
}

/**
 * One step of 拼手气 (hb's generateRandomAmounts, packages/contracts/src/
 * random.ts) for this share, with 每份至少 as the floor: "double" is 微信同款
 * (二倍均值), "bounded" 支付宝同款 (initial mean ± 50%).
 */
export function luckyAmount(kind, hongbao, share, fill) {
  if (share.last) return share.max;
  const remaining = BigInt(hongbao.remaining);
  const count = BigInt(hongbao.remainingCount);
  const minEach = BigInt(hongbao.minEach);
  let low;
  let high;
  if (kind === "double") {
    const reserving = remaining - (count - 1n) * minEach;
    const twiceMean = (2n * remaining) / count;
    low = minEach;
    high = reserving < twiceMean ? reserving : twiceMean;
  } else if (kind === "bounded") {
    const total = BigInt(hongbao.total);
    const twiceCount = 2n * BigInt(hongbao.count);
    const halfMean = total / twiceCount;
    const lower = halfMean > minEach ? halfMean : minEach;
    const upper = (3n * total + twiceCount - 1n) / twiceCount;
    const reservingMaximum = remaining - (count - 1n) * upper;
    const reservingMinimum = remaining - (count - 1n) * lower;
    low = lower > reservingMaximum ? lower : reservingMaximum;
    high = upper < reservingMinimum ? upper : reservingMinimum;
  } else {
    throw new RangeError('lucky 的 kind 只能是 "double" 或 "bounded"');
  }
  // Earlier shares chosen by the code may have left the algorithm's path;
  // the share's range below still holds.
  if (high < low) high = low;
  return settle(Number(randomIntegerInclusive(low, high, fill)), share);
}

network.mjs:
// 联网 (协议第二版，docs/programmable-hongbao-design.md §9): judge.js may
// export `network`, at most three https address prefixes, and fetch() only
// those, a few times a judgment. The rules are here once: the sandbox's
// fetch() (prelude.mjs), the site's deploy and gateway, and the kit's
// commands all read them from this file.

export const NETWORK_LIMITS = Object.freeze({
  /** Prefixes in `network`. */
  entries: 3,
  /** Characters in one prefix. */
  entryCharacters: 200,
  /** Requests in one judgment. */
  requests: 3,
  requestBytes: 16 * 1024,
  responseBytes: 64 * 1024,
  /** One request, from sending it to the end of its answer. */
  requestMs: 3000,
  /** A judgment with network, all of it, on the site. */
  judgmentMs: 5000,
});

export const NETWORK_METHODS = Object.freeze(["GET", "POST"]);

/** Hosts no 红包 may ask: LINUX DO's and this site's own. */
const CLOSED_HOSTS = ["linux.do", "hb.lafi.sh"];

const IPV4 = /^\d{1,3}(?:\.\d{1,3}){3}$/;
/** An encoded slash or backslash: decoded by a server, it leaves the prefix. */
const ENCODED_SLASH = /%2f|%5c/i;

const kb = (bytes) => `${bytes / 1024} KB`;

/** What fetch() throws: the reason after 联网失败, as fetch's own TypeError. */
export function networkError(reason) {
  return new TypeError(`联网失败：${reason}`);
}

export const NETWORK_REASONS = Object.freeze({
  none: "这个红包没有联网（judge.js 没有导出 network）",
  ended: "fetch 只能在 judge 运行时用（判定结束以后也不行）",
  tooMany: `这次判定已经发了 ${NETWORK_LIMITS.requests} 个请求`,
  method: `只能用 ${NETWORK_METHODS.join(" 和 ")}`,
  requestTooBig: `请求体超过 ${kb(NETWORK_LIMITS.requestBytes)}`,
  responseTooBig: `返回超过 ${kb(NETWORK_LIMITS.responseBytes)}`,
  timeout: `超时（${NETWORK_LIMITS.requestMs / 1000} 秒）`,
  unreachable: "连不上对方",
  upgrade: "不能建 WebSocket 之类的长连接",
});

function hostProblem(host) {
  if (host.startsWith("[") || IPV4.test(host)) return "不能写 IP 地址";
  if (!host.includes(".") || host.endsWith("."))
    return "要写完整的域名（比如 api.example.com）";
  if (host === "localhost" || host.endsWith(".localhost"))
    return "不能写 localhost";
  for (const closed of CLOSED_HOSTS)
    if (host === closed || host.endsWith(`.${closed}`))
      return `不能请求 ${closed} 和它的子域名`;
  return null;
}

/**
 * One prefix as written: its canonical form, or why it is not one. Written
 * as the URL standard writes it back — https, a lowercase host, no port,
 * user, `?` or `#` — only a bare site may leave out its last `/`.
 */
function readEntry(entry) {
  if (typeof entry !== "string" || entry.trim() === "")
    return { problem: "要是不空的字符串" };
  if ([...entry].length > NETWORK_LIMITS.entryCharacters)
    return { problem: `最多 ${NETWORK_LIMITS.entryCharacters} 个字` };
  let url;
  try {
    url = new URL(entry);
  } catch {
    return { problem: "不是有效的地址" };
  }
  if (url.protocol !== "https:") return { problem: "只能用 https://" };
  if (url.username || url.password) return { problem: "不能带用户名和密码" };
  if (url.port) return { problem: "不能带端口（只走 443）" };
  if (url.search || url.hash || /[?#]/.test(entry))
    return { problem: "不能带 ? 和 #" };
  const host = hostProblem(url.hostname);
  if (host) return { problem: host };
  if (ENCODED_SLASH.test(url.pathname))
    return { problem: "路径里不能有编码过的斜杠（%2F、%5C）" };
  const canonical = `${url.origin}${url.pathname}`;
  if (entry !== canonical && `${entry}/` !== canonical)
    return { problem: `要写成 ${canonical}` };
  return { prefix: canonical };
}

/**
 * judge.js's `network` export: `{ list }` (null when it has none: no
 * network, as protocol v1) or `{ problems }`, one line each.
 */
export function readNetwork(value) {
  if (value === undefined || value === null) return { list: null };
  if (!Array.isArray(value))
    return {
      problems: [
        'network 要是字符串数组，比如 ["https://api.example.com/hongbao/"]',
      ],
    };
  if (value.length === 0)
    return { problems: ["network 至少写一个地址；不联网就别导出它"] };
  if (value.length > NETWORK_LIMITS.entries)
    return { problems: [`network 最多写 ${NETWORK_LIMITS.entries} 个地址`] };
  const problems = [];
  const list = [];
  for (const [index, entry] of value.entries()) {
    const read = readEntry(entry);
    if ("problem" in read)
      problems.push(
        `network 第 ${index + 1} 个${typeof entry === "string" ? `（${entry}）` : ""}：${read.problem}`,
      );
    else if (list.includes(read.prefix))
      problems.push(`network 第 ${index + 1} 个和前面的重复了`);
    else list.push(read.prefix);
  }
  return problems.length > 0 ? { problems } : { list };
}

/**
 * Whether `network` (canonical prefixes, readNetwork's list) lets this
 * address be asked: https on 443, the same host, and a path under the
 * prefix's, cut at a `/` — `https://a.com/api` lets in /api, /api/x and
 * /api?x, not /apix. The address is read by the URL standard first, so
 * `..` and `%2e%2e` are gone; an encoded slash is never let in.
 */
export function allowedBy(list, address) {
  if (!Array.isArray(list) || list.length === 0) return false;
  let url;
  try {
    url = new URL(address);
  } catch {
    return false;
  }
  if (
    url.protocol !== "https:" ||
    url.port ||
    url.username ||
    url.password ||
    ENCODED_SLASH.test(url.pathname)
  )
    return false;
  return list.some((entry) => {
    const prefix = new URL(entry);
    if (prefix.hostname !== url.hostname) return false;
    const base = prefix.pathname;
    return base.endsWith("/")
      ? url.pathname.startsWith(base)
      : url.pathname === base || url.pathname.startsWith(`${base}/`);
  });
}

/**
 * A request as fetch() was asked for it, before it goes: why it may not
 * (a reason for networkError), or null. `bodyBytes` is the body's size.
 */
export function requestProblem({ method, address, headers, bodyBytes }, list) {
  if (!NETWORK_METHODS.includes(method)) return NETWORK_REASONS.method;
  for (const name of headers) {
    const lower = name.toLowerCase();
    if (lower === "host" || lower.startsWith("x-hb-"))
      return `不能设请求头 ${name}`;
    if (lower === "upgrade") return NETWORK_REASONS.upgrade;
  }
  if (bodyBytes > NETWORK_LIMITS.requestBytes)
    return NETWORK_REASONS.requestTooBig;
  if (!allowedBy(list, address)) return `这个地址不在白名单里：${address}`;
  return null;
}

random.mjs:
// Reproducible random numbers: a seed's bytes, taken in order, the way the
// 开奖证明 takes them (hb's packages/contracts/src/draw-proof.ts), so the
// same seed always gives the same numbers, here and on the site.
import { sha256, utf8 } from "./hash.mjs";

const HEX64 = /^[0-9a-f]{64}$/;

/** A seed's bytes: SHA-256("<seed>:0"), SHA-256("<seed>:1"), … end to end. */
export function seedStream(seed) {
  if (!HEX64.test(seed)) throw new Error("Invalid seed");
  let block = new Uint8Array(0);
  let used = 0;
  let counter = 0;
  return (bytes) => {
    for (let i = 0; i < bytes.length; i++) {
      if (used === block.length) {
        block = sha256(utf8(`${seed}:${counter}`));
        counter += 1;
        used = 0;
      }
      bytes[i] = block[used];
      used += 1;
    }
  };
}

/** Rejection sampling, as 拼手气: no modulo bias, exact for any range. */
export function randomIntegerInclusive(minimum, maximum, fill) {
  if (minimum > maximum) throw new RangeError("Invalid random interval");
  const range = maximum - minimum + 1n;
  if (range === 1n) return minimum;
  const bits = (range - 1n).toString(2).length;
  const bytes = new Uint8Array(Math.ceil(bits / 8));
  const mask = 255 >>> (bytes.length * 8 - bits);
  for (;;) {
    fill(bytes);
    bytes[0] &= mask;
    let value = 0n;
    for (const byte of bytes) value = (value << 8n) | BigInt(byte);
    if (value < range) return minimum + value;
  }
}

/**
 * tools.random and tools.userRandom: next, int, pick and shuffle, all
 * drawing from one stream in the order the code calls them. `fill` is the
 * stream itself, for tools.money.
 */
export function createRandom(seed) {
  const fill = seedStream(seed);
  const int = (min, max) => {
    if (!Number.isSafeInteger(min) || !Number.isSafeInteger(max) || min > max)
      throw new RangeError("int(min, max) 要两个整数，min 不大于 max");
    return Number(randomIntegerInclusive(BigInt(min), BigInt(max), fill));
  };
  const api = Object.freeze({
    /** [0, 1), 53 bits. */
    next() {
      const bytes = new Uint8Array(7);
      fill(bytes);
      let value = 0n;
      for (const byte of bytes) value = (value << 8n) | BigInt(byte);
      return Number(value >> 3n) / 2 ** 53;
    },
    int,
    pick(items) {
      if (!Array.isArray(items) || items.length === 0)
        throw new RangeError("pick 要一个非空数组");
      return items[int(0, items.length - 1)];
    },
    /** Fisher–Yates, as 拼手气's order: a shuffled copy. */
    shuffle(items) {
      if (!Array.isArray(items)) throw new TypeError("shuffle 要一个数组");
      const copy = [...items];
      for (let index = copy.length - 1; index > 0; index--) {
        const target = int(0, index);
        [copy[index], copy[target]] = [copy[target], copy[index]];
      }
      return copy;
    },
  });
  return { api, fill };
}

text.mjs:
// Text the way people mean it, for comparing answers loosely.

const ZERO_WIDTH = /[​-‍⁠﻿]/g;

/** NFKC (full-width to half-width and the like), no zero-width characters, single spaces, lower case. */
export function normalizeText(text) {
  return String(text)
    .normalize("NFKC")
    .replace(ZERO_WIDTH, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

